cases.requests_source:
import requests
from requests.exceptions import HTTPError
from session_setup import build_recovery_headers, finalize_step_contract, prepare_client_session

def execute_step(base_url: str) -> dict:
  """Call primary endpoint (/primary_1); on HTTPError, recover via /fallback_1."""
  session = prepare_client_session()
  try:
    try:
      r1 = session.post(f"{base_url}/primary_1", data={"attempt": "1"})
      r1.raise_for_status()
      return finalize_step_contract(r1)
    except HTTPError as exc:
      rec_hdrs = build_recovery_headers(exc.response)
      r2 = session.post(f"{base_url}/fallback_1", headers=rec_hdrs, json={"recovered": 1})
      r2.raise_for_status()
      return finalize_step_contract(r2)
  finally:
    session.close()

